/** BLAKE3 vs. the reference implementation (python `blake3`, vectors generated by scripts/gen-blake3-vectors.py). */
import { readFileSync } from 'node:fs';
import { blake3 } from '../../src/core/sha/blake3.js';
import { bytesToHex, hexToBytes } from '../../src/utils/encoding.js';

const doc = JSON.parse(readFileSync(new URL('../vectors/blake3-vectors.json', import.meta.url), 'utf8'));

describe('BLAKE3', () => {
  it('known answers: empty and "abc"', () => {
    expect(bytesToHex(blake3.hashSync(new Uint8Array(0)))).toBe('af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262');
    expect(bytesToHex(blake3.hashSync(new TextEncoder().encode('abc')))).toBe('6437b3ac38465133ffb63b75273a8db548c558465d79db03fd359c6cd5bd9d85');
  });
  it('matches the reference for hash / XOF across chunk and tree boundaries', () => {
    for (const v of doc.hash) expect(bytesToHex(blake3.hashSync(hexToBytes(v.input), v.outLen))).toBe(v.output);
  });
  it('matches the reference for keyed hash', () => {
    for (const v of doc.keyed) expect(bytesToHex(blake3.keyedHashSync(hexToBytes(v.key), hexToBytes(v.input), v.outLen))).toBe(v.output);
  });
  it('matches the reference for derive_key', () => {
    for (const v of doc.derive) expect(bytesToHex(blake3.deriveKeySync(v.context, hexToBytes(v.input), v.outLen))).toBe(v.output);
  });
  it('rejects bad key size and output length', () => {
    expect(() => blake3.keyedHashSync(new Uint8Array(16), new Uint8Array(1))).toThrow();
    expect(() => blake3.hashSync(new Uint8Array(1), 0)).toThrow();
  });
});
